const c=$('Prepare briefing').first().json;
const ai=$input.first().json;
const overview=typeof ai.text==='string' && !ai.error?ai.text.trim().slice(0,220):'';
const header='SPORTS RADAR · NEXT 7 DAYS\nAll times: Europe/Paris\n';
// One digest = one Telegram message. Keep well below Telegram's size limit.
const budget=3400;
const intro=overview?'\n'+overview+'\n':'';
const tail=c.warning+'\n\n/daily on · /daily off · /myteams';
const room=budget-header.length-intro.length-tail.length;
let body=c.body;
if(body.length>room) {
 const paragraphs=body.split('\n\n'); let out=''; let n=0;
 for(const paragraph of paragraphs) {if((out+paragraph).length>room-100) break;out+=(out?'\n\n':'')+paragraph;n++;}
 body=out+`\n\n${paragraphs.length-n} more events omitted to fit this message.`;
}
const text=header+intro+'\n'+body+tail;
const html=text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
return [{json:{chat_id:c.chat_id,mode:c.mode,local_date:c.local_date,text:html}}];

const c=$input.first().json;
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const parisDay=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const fmt=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Paris',weekday:'short',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const start=Date.parse(c.now),end=Date.parse(c.end);
const seen=new Set();
const events=c.events.filter(e=>{
 if(seen.has(e.id)) return false;
 const pref=c.prefs.some(p=>p.sport===e.sport && (e.sport==='f1'||(p.aliases||[]).some(a=>(e.participants||[]).some(t=>norm(t)===norm(a)))));
 if(!pref) return false;
 const time=e.at?Date.parse(e.at):NaN;
 const within=Number.isFinite(time)?time>=start&&time<end:(e.date && e.date>=parisDay(new Date(start)) && e.date<=parisDay(new Date(end)));
 if(!within) return false;
 seen.add(e.id);return true;
}).sort((a,b)=>(a.at||a.date).localeCompare(b.at||b.date));
const pretty=e=>e.at?fmt.format(new Date(e.at)):`${e.date} · time TBC`;
const lines=events.map(e=>`${pretty(e)} | ${e.competition}\n${e.title}`);
const warning=c.warnings.length?'\n\nCalendar status:\n'+[...new Set(c.warnings)].join('\n'):'';
let body;
if(!c.prefs.length) body='Choose your teams and drivers first. Tap Home, choose a sport, then select a team or driver.';
else if(!lines.length) body=c.warnings.length?'No events could be shown from the calendars that were available. The unavailable calendars may still have events.':'No upcoming events found for your preferences in the next 7 days. Coverage depends on the selected providers.';
else body=lines.join('\n\n');
const prompt=JSON.stringify({events:events.slice(0,30).map(e=>({sport:e.sport,title:e.title,date:pretty(e)})),unavailable:c.warnings});
return [{json:{...c,events,body,warning,prompt,has_events:events.length>0}}];

const c=JSON.parse(JSON.stringify($('Next year needed?').first().json));
const r=$input.first().json;
const races=r.MRData?.RaceTable?.Races;
if (r.error || !Array.isArray(races)) c.warnings.push('Next-year F1 calendar unavailable — please try again later.');
else for (const race of races) {
 for (const [kind,session] of [['Race',race],['Qualifying',race.Qualifying]]) {
  if (!session?.date) continue;
  c.events.push({id:`f1-${race.season}-${race.round}-${kind}`,sport:'f1',title:`${race.raceName} — ${kind}`,
   at:session.time?`${session.date}T${session.time}`:null,date:session.date,participants:[],competition:'Formula 1'});
 }
}
return [{json:c}];

const c=JSON.parse(JSON.stringify($('F1 needed?').first().json));
const r=$input.first().json;
const races=r.MRData?.RaceTable?.Races;
if (r.error || !Array.isArray(races)) c.warnings.push('F1 calendar unavailable — please try again later.');
else for (const race of races) {
 for (const [kind,session] of [['Race',race],['Qualifying',race.Qualifying]]) {
  if (!session?.date) continue;
  c.events.push({id:`f1-${race.season}-${race.round}-${kind}`,sport:'f1',title:`${race.raceName} — ${kind}`,
   at:session.time?`${session.date}T${session.time}`:null,date:session.date,participants:[],competition:'Formula 1'});
 }
}
return [{json:c}];

const c = JSON.parse(JSON.stringify($('NBA needed?').first().json));
c.events = c.events || [];
c.warnings = c.warnings || [];
const seen = new Set(c.events.map(e => e.id));
const start = Date.parse(c.now);
const end = Date.parse(c.end);
if (!Number.isFinite(start) || !Number.isFinite(end)) {
  throw new Error('Missing date window. Run this through /events.');
}
let lastPage;
for (const item of $input.all()) {
  const r = item.json.body || item.json;
  lastPage = r;
  if (item.json.error || r.error || !Array.isArray(r.data)) {
    c.warnings.push('NBA calendar unavailable or incomplete — check BALLDONTLIE credentials and request limits.');
    continue;
  }
  for (const g of r.data) {
    const status = String(g.status || '').toLowerCase();
    if (g.postponed || /final|postponed|cancel|suspend|abandon|delay/.test(status)) continue;
    if (g.status_state && g.status_state !== 'scheduled') continue;
    if (!g.status_state && Number(g.period || 0) !== 0) continue;
    const at = typeof g.datetime === 'string' && g.datetime.includes('T') ? Date.parse(g.datetime) : NaN;
    if (!Number.isFinite(at)) {
      c.warnings.push('Some NBA games have no confirmed start time and are not shown.');
      continue;
    }
    if (at < start || at >= end) continue;
    const home = g.home_team;
    const away = g.visitor_team;
    if (g.id == null || !home?.full_name || !away?.full_name) {
      c.warnings.push('Some NBA games have incomplete team data and are not shown.');
      continue;
    }
    const id = 'basketball-bdl-' + g.id;
    if (seen.has(id)) continue;
    seen.add(id);
    c.events.push({
      id,
      sport: 'basketball',
      title: home.full_name + ' vs ' + away.full_name,
      at: new Date(at).toISOString(),
      participants: [home.full_name, home.name, home.abbreviation, away.full_name, away.name, away.abbreviation].filter(Boolean),
      competition: 'NBA'
    });
  }
}
if (lastPage?.meta?.next_cursor != null) {
  c.warnings.push('NBA calendar incomplete — check pagination in Get NBA calendar.');
}
c.warnings = [...new Set(c.warnings)];
return [{ json: c }];

const c=JSON.parse(JSON.stringify($('Football needed?').first().json));
const r=$input.first().json;
if (r.error || !Array.isArray(r.matches)) c.warnings.push('Football calendar unavailable — check the API key, access and request limit.');
else for (const m of r.matches) {
 if (!['SCHEDULED','TIMED'].includes(m.status)) continue;
 c.events.push({id:'football-'+m.id,sport:'football',title:`${m.homeTeam?.name||'?'} vs ${m.awayTeam?.name||'?'}`,
 at:m.utcDate,participants:[m.homeTeam?.name,m.homeTeam?.shortName,m.awayTeam?.name,m.awayTeam?.shortName].filter(Boolean),competition:m.competition?.name||'Football'});
}
return [{json:c}];

parameters.query:
WITH claimed AS (
 INSERT INTO sports_radar.deliveries(chat_id,local_date,status)
 SELECT $1::text,$2::date,'pending' WHERE $3::text='daily'
 ON CONFLICT DO NOTHING RETURNING chat_id
) SELECT $4::jsonb AS context WHERE $3::text<>'daily' OR EXISTS(SELECT 1 FROM claimed);

parameters.jsCode:
const row=$input.first().json;
const c=typeof row.context==='string'?JSON.parse(row.context):(row.context||row);
if (!/^\d+$/.test(String(c.chat_id))) throw new Error('A private Telegram chat_id is required.');
const now=new Date();
const end=new Date(now.getTime()+7*86400000);
const day=d=>d.toISOString().slice(0,10);
const mode=c.mode==='daily'?'daily':'manual';
return [{json:{...c,chat_id:String(c.chat_id),mode,prefs:c.prefs||[],
 now:now.toISOString(),end:end.toISOString(),from:day(now),to:day(new Date(end.getTime()+86400000)),
 year:now.getUTCFullYear(),end_year:end.getUTCFullYear(),
 nba_season:now.getUTCMonth()>=8?now.getUTCFullYear():now.getUTCFullYear()-1,
 local_date:new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(now),
 events:[],warnings:[]}}];

const input=$input.first().json;
let parsed;
try { parsed=typeof input.text==='string'?JSON.parse(input.text):input.output; } catch {}
const valid=!input.error && parsed && typeof parsed==='object' && !Array.isArray(parsed) &&
 Object.keys(parsed).length===1 && typeof parsed.overview==='string' &&
 parsed.overview.trim().length>0 && parsed.overview.trim().length<=180 &&
 !/[\r\n]|https?:\/\/|\d{1,2}:\d{2}|```/.test(parsed.overview);
return [{json:{text:valid?parsed.overview.trim():'',overview_valid:Boolean(valid),
 validation:valid?'valid':'AI output did not meet the overview schema; using the verified event list.'}}];
